Python example catching typed errors:
from redwood import Client, exceptions
client = Client()
try:
    resp = client.generate('...')
except exceptions.RateLimitError as e:
    print('Rate limited, retry after', e.action_hint)
except exceptions.TransientError as e:
    # SDK has retried by default; if we've reached here consider manual backoff
    handle_transient(e)

# Streaming example
for chunk in client.stream_chat('...'):
    try:
        process(chunk)
    except exceptions.StreamClosedError as e:
        if e.resume_token:
            # opt-in resume helper (not default)
            client.stream_chat_resume(e.resume_token)
        else:
            raise

TypeScript example using async iterator:
import { RedwoodClient, RedwoodError, isRetriable } from '@redwood/sdk'
const client = new RedwoodClient()
try {
  for await (const chunk of client.chatStream('...')) {
    process(chunk)
  }
} catch (err) {
  if (isRetriable(err)) {
    // application policy: exponential backoff + jitter
  } else {
    console.error('unrecoverable', err.code, err.message)
  }
}

